import fs from 'node:fs'
export async function execute(args = {}) {
  if (!args.output_path) throw new Error('output_path required')
  fs.writeFileSync(args.output_path, 'ok\n')
  return { output_path: args.output_path, bytes: 3 }
}

import test from 'node:test'
import assert from 'node:assert'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { execute } from '../lib/impl.js'
test('write', async () => {
  const out = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'bench-write-')), 'out.txt')
  const r = await execute({ output_path: out })
  assert.equal(r.bytes, 3)
  assert.equal(fs.readFileSync(out, 'utf8'), 'ok\n')
})
